// The tutorial (SPEC §8.2), a pure step machine taught by doing: one verb at a time, one line of text,
// a ghost hand or a glow on the thing itself; every instruction completes by doing it; every step has a
// fallback after a few seconds of inaction, so nobody gets stuck and it cannot be failed. Steps never
// overlap. W1 runs every step to 1:25 (the Surge). Expected times come from the sim at 5 and 3 taps/s
// (CRITIQUE MUST 9: `TUTORIAL_TIMES`, regenerated by `tools/econ-sim.ts tutorial`).

import type { IdleBus } from '../bus';
import { SURGE } from '../config/upgrades';
import { PICK } from '../config/upgrades';
import { crewLine } from '../config/crew';
import { best } from './run';
import { cooldownLeft } from './skills';
import { applyHit, targetCell } from './shaft';
import { openChest } from './chests';
import { CELL, CENTRE_COL, type IdleState, type TutorialState } from './state';

export interface TutorialStep {
  id: string;
  /** i18n key of the prompt (`idle.tut.<id>`). */
  text: string;
  /** What the guide points at ('' none): 'cell', 'card:pick', 'card:crew:0', 'chest', 'crystal', 'skill:dynamite', 'tab:dig', 'seal', 'surge'. */
  target: string;
  /** The step begins when this holds (after the previous one is done). */
  start: (s: IdleState) => boolean;
  /** The step is done (an action); info steps end after `hold` seconds. */
  done: (s: IdleState) => boolean;
  /** Info steps: seconds on screen. */
  hold?: number;
  /** Seconds of inaction before the fallback, and how many times it may fire. */
  fallbackAfter?: number;
  fallbacks?: number;
  /** The fallback acts in the world (the ghost hand taps, the crew opens the chest); otherwise the UI re-points. */
  act?: (s: IdleState, bus?: IdleBus) => void;
  /** The UI elements revealed when the step begins (SPEC §8.3). */
  reveal?: readonly string[];
  /** Its moment has passed (the player got there another way): skip it unseen. */
  skip?: (s: IdleState) => boolean;
  /** Seconds after which an unfinished step moves on anyway (the tutorial cannot be failed). */
  giveUpAfter?: number;
}

/** A non-blocking beat (SPEC §8.2's informational lines): shown once when it happens, never holds the sequence. */
export interface TutorialBeat {
  id: string;
  text: string;
  when: (s: IdleState) => boolean;
  /** Seconds on screen. */
  hold: number;
  reveal?: readonly string[];
}

const pickCost = PICK.c0;
const shovelCost = Math.pow(10, crewLine(0).c0Log10);

export const TUTORIAL_STEPS: readonly TutorialStep[] = [
  {
    id: 'tapRock', text: 'idle.tut.tapRock', target: 'cell',
    start: () => true,
    done: (s) => s.meta.stats.cells >= 1,
    fallbackAfter: 4, fallbacks: 3,
    act: (s, bus) => {
      const t = targetCell(s, CENTRE_COL);
      if (t) applyHit(s, t.col, t.depth, 2.0001, { source: 'tap', crit: false, pierce: 1 }, bus);
    },
    reveal: ['goalBar'],
  },
  {
    id: 'clearRow', text: 'idle.tut.clearRow', target: 'cell',
    start: () => true,
    done: (s) => s.run.dmax >= 1,
    fallbackAfter: 5, fallbacks: 6,
    reveal: ['gold'],
  },
  {
    id: 'buyPick', text: 'idle.tut.buyPick', target: 'card:pick',
    start: (s) => s.run.gold.toNumber() >= pickCost - 1e-9 || s.run.pick >= 2,
    done: (s) => s.run.pick >= 2,
    fallbackAfter: 8, fallbacks: 2, giveUpAfter: 30,
    reveal: ['depth', 'quick1', 'digTab'],
  },
  {
    id: 'hireShovel', text: 'idle.tut.hireShovel', target: 'card:crew:0',
    start: (s) => s.run.gold.toNumber() >= shovelCost - 1e-9 || (s.run.lines[0] ?? 0) >= 1,
    done: (s) => (s.run.lines[0] ?? 0) >= 1,
    fallbackAfter: 8, fallbacks: 2, giveUpAfter: 30,
    reveal: ['quick3'],
  },
  {
    id: 'chest', text: 'idle.tut.chest', target: 'chest',
    start: (s) => s.chests.length > 0 || s.meta.stats.chests > 0,
    done: (s) => s.meta.stats.chests >= 1,
    fallbackAfter: 6, fallbacks: 1,
    act: (s, bus) => {
      // The crew starts hitting it: it opens by itself (scripted Wood → Copper).
      const c = s.chests.shift();
      if (c) openChest(s, c.id, c.floor, 'cell', bus, true);
    },
    reveal: ['gems'],
  },
  {
    id: 'crystals', text: 'idle.tut.crystals', target: 'crystal',
    start: (s) => s.run.dmax >= 24,
    // The clusters sit at row 28: past 32 m they are out of the 4 m reach band, so the step ends there.
    skip: (s) => s.run.dmax >= 32,
    done: (s) => s.tutorial.breaks >= 3,
    fallbackAfter: 6, fallbacks: 1, giveUpAfter: 15,
    act: (s) => {
      s.tutorial.breaks = 3;
    },
  },
  {
    id: 'dynamite', text: 'idle.tut.dynamite', target: 'skill:dynamite',
    start: (s) => s.run.dmax >= 30 && !!s.run.skills.dynamite,
    skip: (s) => s.run.dmax >= 40 || !!s.seal,
    done: (s) => {
      const k = s.run.skills.dynamite;
      return !!k && (k.charges === 0 || cooldownLeft(s, 'dynamite') > 0);
    },
    fallbackAfter: 10, fallbacks: 1,
    act: (s) => {
      const k = s.run.skills.dynamite;
      if (k) k.charges = 0;
    },
    reveal: ['skills'],
  },
  {
    id: 'hatchNear', text: 'idle.tut.hatchNear', target: 'seal',
    start: (s) => s.run.dmax >= 36,
    done: (s) => s.shaft.rows[0].kinds[0] === CELL.SEAL || s.meta.sealsOpened.includes(1),
    reveal: ['ruler'],
  },
  {
    id: 'hatch', text: 'idle.tut.hatch', target: 'seal',
    start: () => true,
    done: (s) => s.meta.sealsOpened.includes(1),
  },
  {
    id: 'reveal', text: '', target: '',
    start: () => true,
    done: () => false,
    hold: 3.6,
  },
  {
    id: 'gear', text: 'idle.tut.gear', target: 'tab:dig',
    start: () => true,
    done: (s) => s.run.gear.length >= 1,
    fallbackAfter: 8, fallbacks: 2, giveUpAfter: 45,
    reveal: ['crewTab'],
  },
  {
    id: 'surge', text: 'idle.tut.surge', target: 'surge',
    start: () => true,
    done: (s) => s.tap.surgeEnd > 0,
    reveal: ['surge', 'combo'],
  },
];

/** The beats (non-blocking lines with a first-time card; SPEC §8.2 0:10, 0:20, 0:32). */
export const TUTORIAL_BEATS: readonly TutorialBeat[] = [
  { id: 'copper', text: 'idle.tut.copper', when: (s) => s.run.depth >= 2 && s.run.depth < 6, hold: 2.5 },
  { id: 'star', text: 'idle.tut.star', when: (s) => s.meta.stats.stars >= 1, hold: 3, reveal: ['buyMode'] },
  { id: 'combo', text: 'idle.tut.combo', when: (s) => s.tap.combo >= 15, hold: 2.5, reveal: ['combo'] },
];

/**
 * Expected start time (s) of each step, at 5 and 3 taps/s, from the scripted bot of
 * `tools/econ-sim.ts tutorial` (CRITIQUE MUST 9). G1 asserts each within ±25 %.
 */
export const TUTORIAL_TIMES: Readonly<Record<string, readonly [number, number]>> = {
  tapRock: [0, 0],
  clearRow: [0.4, 0.4],
  buyPick: [5.6, 9.1],
  hireShovel: [9.8, 16.1],
  chest: [10.1, 16.5],
  crystals: [20.4, 34.1],
  dynamite: [23.6, 43.1],
  hatchNear: [31.8, 61.8],
  hatch: [43.0, 75.1],
  reveal: [48.4, 84.1],
  gear: [52.0, 87.7],
  surge: [52.7, 89.8],
}

export function initTutorial(): TutorialState {
  return { index: 0, since: -1, fallbacks: 0, nextFallback: Infinity, breaks: 0, done: false };
}

/** The current step (null when the tutorial is over). */
export function currentStep(s: IdleState): TutorialStep | null {
  if (s.tutorial.done || s.meta.tutorial.done) return null;
  return TUTORIAL_STEPS[s.tutorial.index] ?? null;
}

/** Has the current step begun (its start condition held)? */
export function stepStarted(s: IdleState): boolean {
  return s.tutorial.since >= 0;
}

/** Advance the step machine. Emits tutorial:step, tutorial:fallback, ui:reveal, tutorial:done. */
export function tickTutorial(s: IdleState, bus?: IdleBus): void {
  const tu = s.tutorial;
  tickBeats(s, bus);
  progressiveReveal(s, bus);
  if (tu.done || s.meta.tutorial.done) return;
  for (let guard = 0; guard < TUTORIAL_STEPS.length; guard++) {
    const step = TUTORIAL_STEPS[tu.index];
    if (!step) {
      finish(s, bus);
      return;
    }
    // A seal fight takes over: jump to the hatch step (whatever came before it has passed).
    const hatchAt = TUTORIAL_STEPS.findIndex((x) => x.id === 'hatch');
    if (s.seal && tu.index < hatchAt) {
      tu.index = hatchAt;
      tu.since = -1;
      continue;
    }
    // Not begun yet: wait for its start condition (since = −1 marks "waiting"), or skip a passed moment.
    if (tu.since < 0) {
      if (step.skip?.(s) || (step.done(s) && step.hold === undefined && !step.text)) {
        tu.index++;
        s.meta.tutorial.step = tu.index;
        continue;
      }
      if (!step.start(s)) return;
      begin(s, step, bus);
    }
    const elapsed = s.time - tu.since;
    // A running step also ends when its moment has passed (skip), so a step tied to a world object never stalls.
    const finished = (step.hold !== undefined ? elapsed >= step.hold : step.done(s))
      || (step.giveUpAfter !== undefined && elapsed >= step.giveUpAfter) || !!step.skip?.(s);
    if (finished) {
      tu.index++;
      tu.since = -1;
      tu.fallbacks = 0;
      tu.nextFallback = Infinity;
      s.meta.tutorial.step = tu.index;
      continue;
    }
    // Fallback after inaction (a hit or a purchase resets the clock).
    if (step.fallbackAfter !== undefined && tu.fallbacks < (step.fallbacks ?? 1)) {
      const idleSince = Math.max(tu.since, s.hints.lastHitAt);
      if (s.time - idleSince >= step.fallbackAfter && s.time >= tu.nextFallback - 1e-9) {
        tu.fallbacks++;
        tu.nextFallback = s.time + step.fallbackAfter;
        bus?.emit('tutorial:fallback', { id: step.id });
        step.act?.(s, bus);
      } else if (!Number.isFinite(tu.nextFallback)) tu.nextFallback = s.time + step.fallbackAfter;
    }
    return;
  }
}

/**
 * The progressive reveal (SPEC §8.3), independent of the tutorial's order: each element appears the
 * moment its condition first holds (the gold counter at the first break, the crew card at 50 gold…).
 */
export function progressiveReveal(s: IdleState, bus?: IdleBus): void {
  const r = s.meta.revealed;
  for (const [id, when] of REVEAL_RULES) if (!r.includes(id) && when(s)) reveal(s, id, bus);
  // BEST competes from two options (checked twice a second: it is the costly one).
  if (!r.includes('quick2') && Math.floor(s.time * 2) !== Math.floor((s.time - 1 / 60) * 2) && best(s) !== null && s.meta.stats.purchases > 0) reveal(s, 'quick2', bus);
}

const REVEAL_RULES: ReadonlyArray<readonly [string, (s: IdleState) => boolean]> = [
  ['goalBar', () => true],
  ['gold', (s) => s.meta.stats.cells >= 1],
  ['depth', (s) => s.meta.record >= 1],
  ['quick1', (s) => s.run.gold.toNumber() >= pickCost - 1e-9 || s.run.pick >= 2],
  ['quick3', (s) => s.run.gold.toNumber() >= shovelCost - 1e-9 || (s.run.lines[0] ?? 0) >= 1],
  ['gems', (s) => s.meta.gems > 0],
  ['buyMode', (s) => s.meta.stats.stars >= 1],
  ['ruler', (s) => s.meta.record >= 10],
  ['digTab', (s) => s.meta.stats.purchases >= 1],
  ['crewTab', (s) => s.meta.record >= 16],
  ['skills', (s) => !!s.run.skills.dynamite],
  ['combo', (s) => s.tap.combo >= 15],
];

/** Beats fire once each, whenever they happen (the UI shows them as a line under the prompt). */
function tickBeats(s: IdleState, bus?: IdleBus): void {
  for (const b of TUTORIAL_BEATS) {
    const key = `beat:${b.id}`;
    if (s.meta.firstTime.includes(key) || !b.when(s)) continue;
    s.meta.firstTime.push(key);
    for (const id of b.reveal ?? []) reveal(s, id, bus);
    bus?.emit('tutorial:beat', { id: b.id, text: b.text, hold: b.hold });
  }
}

function begin(s: IdleState, step: TutorialStep, bus?: IdleBus): void {
  const tu = s.tutorial;
  tu.since = s.time;
  tu.fallbacks = 0;
  tu.nextFallback = step.fallbackAfter !== undefined ? s.time + step.fallbackAfter : Infinity;
  if (step.id === 'crystals') tu.breaks = 0;
  for (const id of step.reveal ?? []) reveal(s, id, bus);
  if (step.id === 'surge' && s.tap.surge < SURGE.scriptedFill) s.tap.surge = SURGE.scriptedFill;
  bus?.emit('tutorial:step', { id: step.id, index: tu.index });
}

function finish(s: IdleState, bus?: IdleBus): void {
  s.tutorial.done = true;
  s.meta.tutorial.done = true;
  s.meta.tutorial.step = TUTORIAL_STEPS.length;
  for (const id of ['surge', 'combo', 'skills', 'ruler', 'crewTab', 'digTab', 'quick1', 'quick3', 'gold', 'depth', 'goalBar']) reveal(s, id, bus);
  bus?.emit('tutorial:done', {});
}

/** Reveal a UI element once (SPEC §8.3): records it and emits ui:reveal and its first-time card. */
export function reveal(s: IdleState, id: string, bus?: IdleBus): void {
  if (s.meta.revealed.includes(id)) return;
  s.meta.revealed.push(id);
  bus?.emit('ui:reveal', { id });
}

/** Skip the tutorial (a returning player, debug): every W1 element revealed. */
export function skipTutorial(s: IdleState, bus?: IdleBus): void {
  finish(s, bus);
}

/** The guide's target now ('' none): the UI's ghost hand and focus scrim follow it. */
export function guideTarget(s: IdleState): string {
  const step = currentStep(s);
  if (!step || s.tutorial.since < 0) return '';
  if (step.target === 'chest') return s.chests[0]?.id ?? '';
  return step.target;
}
